<script setup>
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue'
import { can } from '../../permissions.js'
import { createClientId } from '../../clientId.js'
import { maintenanceWrite,maintenanceRevision } from '../../maintenance/api.js'
import { scenarioPayload,orderedAdjustment,eligibleObservations,stateLabel,verificationLabel,maintenanceTime,money,createAssetRevisionLookup } from '../../maintenance/helpers.js'
const props=defineProps({items:Array,assets:Array,records:Array,costs:Array,observations:Array,selected:Object,run:Object,snapshot:Object,deviceId:String})
const emit=defineEmits(['refresh','select','evaluate'])
const dialog=ref(false),operation=ref('draft'),busy=ref(false),error=ref(''),target=ref(null),key=ref(''),form=reactive({}),reason=ref(''),order=ref([]),selectedCandidates=ref([]),fixedDecision=ref(null),historicalAssets=ref([]),historyError=ref(''),formLoading=ref(false)
let generation=0,historyGeneration=0,disposed=false
const allAssets=computed(()=>[...props.assets,...historicalAssets.value.filter(row=>!props.assets.some(a=>a.id===row.id))])
const rows=computed(()=>props.items.filter(row=>!props.deviceId||row.deviceIds.includes(props.deviceId))),assetName=id=>allAssets.value.find(a=>a.id===id)?.body.name||'固定实物版本',candidateName=c=>assetName(c.assetRevisionId)+' · '+stateLabel(c.action)
const assetOptions=c=>allAssets.value.filter(row=>row.id===c.assetRevisionId||!props.deviceId||row.deviceIds.includes(props.deviceId))
const quoteOptions=c=>props.costs.filter(row=>{const asset=allAssets.value.find(a=>a.id===c.assetRevisionId),b=row.body;return asset&&b.sourceKind==='ASSET_INSTANCE'&&b.sourceId===asset.resourceId&&b.type==='ESTIMATE'&&b.currency===form.currency&&b.planningStart===form.planning?.[0]&&b.planningEnd===form.planning?.[1]})
const observationOptions=c=>eligibleObservations(props.observations,allAssets.value.find(a=>a.id===c.assetRevisionId),allAssets.value)
const defectOptions=c=>{const asset=allAssets.value.find(a=>a.id===c.assetRevisionId);return asset?props.records.filter(r=>allAssets.value.find(a=>a.id===r.body.assetRevisionId)?.resourceId===asset.resourceId):[]}
const lookupAssets=createAssetRevisionLookup(()=>allAssets.value,maintenanceRevision)
async function resolveAssets(ids,isCurrent){const result=await lookupAssets(ids,isCurrent);if(!result)return false;for(const row of result.items)if(!allAssets.value.some(a=>a.id===row.id))historicalAssets.value.push(row);if(result.errors.length)throw Error('固定历史实物资料无法读取，请重试：'+result.errors[0].message);return true}
async function loadReferencedAssets(){const token=++historyGeneration;historyError.value='';try{await resolveAssets([...props.items.flatMap(row=>row.body.candidates.map(c=>c.assetRevisionId)),...(props.selected?.body.candidates||[]).map(c=>c.assetRevisionId),...props.records.map(row=>row.body.assetRevisionId)],()=>token===historyGeneration&&!disposed)}catch(cause){if(token===historyGeneration&&!disposed)historyError.value=cause.message}}
async function resolveObservationAssets(c){const token=generation,id=c.assetRevisionId,isCurrent=()=>token===generation&&!disposed&&dialog.value&&operation.value==='draft'&&c.assetRevisionId===id&&form.candidates.includes(c);try{if(!await resolveAssets([id],isCurrent))return;const asset=allAssets.value.find(a=>a.id===id);if(!asset)return;await resolveAssets(props.observations.filter(r=>r.deviceIds.includes(asset.body.deviceId)).map(r=>r.parameters?.observation?.afterAssetRevisionId),isCurrent)}catch(cause){if(isCurrent())error.value=cause.message}}
function candidate(row){return{id:row?.id||createClientId(),assetRevisionId:row?.assetRevisionId||'',action:row?.action||'INSPECT',requiredTier:row?.requiredTier??null,tierBasis:row?.tierBasis||'',observationRunId:row?.observationRunId||'',defectBasisIds:[...(row?.defectBasisIds||[])],quoteRevisionId:row?.quoteRevisionId||'',constraints:(row?.constraints||[]).join('\n')}}
function resetEditor(){generation++;busy.value=false;formLoading.value=false;error.value=''}
async function edit(row){resetEditor();const token=generation;target.value=row;const b=row?.body||{};Object.assign(form,{resourceId:row?.resourceId||createClientId(),expectedVersion:row?.version||0,name:b.name||'',useFinance:!!b.useFinance,currency:b.currency||'CNY',budget:b.budget??'',planning:b.planningStart?[b.planningStart,b.planningEnd]:null,candidates:b.candidates?.map(candidate)||[candidate()]});operation.value='draft';reason.value='';key.value=createClientId();dialog.value=true;formLoading.value=true;try{if(await resolveAssets(form.candidates.map(c=>c.assetRevisionId),()=>token===generation&&!disposed))for(const c of form.candidates)resolveObservationAssets(c)}catch(cause){if(token===generation&&!disposed)error.value=cause.message}finally{if(token===generation&&!disposed)formLoading.value=false}}
function begin(row,op){resetEditor();target.value=row;fixedDecision.value=op==='decision'?{run:props.run,snapshot:props.snapshot}:null;operation.value=op;reason.value='';order.value=row.body.candidates.map(c=>c.id);selectedCandidates.value=[];key.value=createClientId();dialog.value=true}
function move(i,d){const values=[...order.value];[values[i],values[i+d]]=[values[i+d],values[i]];order.value=values}
async function save(){if(busy.value||!dialog.value||disposed)return;const token=generation;busy.value=true;error.value='';try{let value;if(operation.value==='draft'){if(!await resolveAssets(form.candidates.map(c=>c.assetRevisionId),()=>token===generation&&!disposed))return;value=await maintenanceWrite('investment-scenarios','','',scenarioPayload(form,allAssets.value,key.value))}else{if(!reason.value.trim())throw Error('人工操作须填写明确依据');const id=target.value.resourceId,base={expectedVersion:target.value.version,idempotencyKey:key.value,reason:reason.value.trim()};if(operation.value==='adjustment')value=await maintenanceWrite('investment-scenarios',id,'adjustments',{...base,candidateOrder:orderedAdjustment(order.value,target.value.body.candidates)});else if(operation.value==='decision'){if(!fixedDecision.value?.run||!fixedDecision.value?.snapshot||!selectedCandidates.value.length)throw Error('请选择固定排序版本及实际决定候选');value=await maintenanceWrite('investment-scenarios',id,'decisions',{...base,evaluationRunId:fixedDecision.value.run.id,selectedCandidateIds:selectedCandidates.value})}else value=await maintenanceWrite('investment-scenarios',id,'actions',{...base,action:operation.value})}if(token!==generation||disposed)return;dialog.value=false;emit('refresh');emit('select',value)}catch(cause){if(token===generation&&!disposed)error.value=cause.status===409?'方案或固定排序版本已变化，请刷新后重新核对。':cause.message}finally{if(token===generation&&!disposed)busy.value=false}}
watch(()=>[props.items.flatMap(row=>row.body.candidates.map(c=>c.assetRevisionId)).join(','),props.records.map(row=>row.body.assetRevisionId).join(','),props.assets.map(row=>row.id).join(','),props.selected?.id],loadReferencedAssets,{immediate:true})
watch(dialog,(value,previous)=>{if(!value&&previous)resetEditor()},{flush:'sync'})
onBeforeUnmount(()=>{disposed=true;generation++;historyGeneration++})
</script>
<template><section class="maintenance-stack"><div class="maintenance-toolbar"><p class="maintenance-hint">人工必需分层后，依次比较已核实未解除缺陷、人工重要性、同口径故障率、已知离线时长。资料不足留在同层待补区。</p><ui-button v-if="can('POST /api/v1/investment-scenarios')" size="small" type="primary" @click="edit()">建立投入方案</ui-button></div><ui-alert v-if="historyError" :title="historyError" type="error" :closable="false"/><div class="maintenance-table-scroll"><ui-table :data="rows" empty-text="当前范围暂无投入方案。"><ui-table-column label="方案 / 固定配置" min-width="200"><template #default="{row}">{{row.body.name}}<p class="maintenance-meta">版本 {{row.version}} · {{stateLabel(row.body.status)}} · {{row.body.candidates.length}} 个实际候选</p></template></ui-table-column><ui-table-column label="规划 / 资金范围" min-width="250"><template #default="{row}">{{maintenanceTime(row.body.planningStart)}} 至 {{maintenanceTime(row.body.planningEnd)}}<p class="maintenance-meta">{{row.body.useFinance?row.body.currency+' · 预算 '+money(row.body.budget):'不使用资金因素'}}</p></template></ui-table-column><ui-table-column label="操作" min-width="300"><template #default="{row}"><div class="maintenance-actions"><ui-button text size="small" :data-maintenance-scenario="row.resourceId" @click="emit('select',row)">读取方案与排序</ui-button><ui-button v-if="row.body.status==='DRAFT'&&can('POST /api/v1/investment-scenarios')" text size="small" @click="edit(row)">编辑草稿</ui-button><ui-button v-if="can('POST /api/v1/investment-scenarios/:id/evaluate')&&row.body.status!=='ARCHIVED'" text size="small" @click="emit('evaluate',row)">计算固定排序</ui-button><ui-button v-if="row.body.status==='DRAFT'&&can('POST /api/v1/investment-scenarios/:id/actions')" text size="small" @click="begin(row,'REVIEW')">登记方案审核</ui-button><ui-button v-if="row.body.status==='DECIDED'&&can('POST /api/v1/investment-scenarios/:id/actions')" text size="small" @click="begin(row,'ARCHIVE')">归档已决定方案</ui-button></div></template></ui-table-column></ui-table></div>
<article v-if="selected" class="maintenance-card maintenance-stack"><div class="maintenance-toolbar"><h3>{{selected.body.name}} · 当前方案版本 {{selected.version}}</h3><div class="maintenance-actions"><ui-button v-if="can('POST /api/v1/investment-scenarios/:id/adjustments')&&['DRAFT','REVIEWED'].includes(selected.body.status)" size="small" @click="begin(selected,'adjustment')">保存人工完整顺序</ui-button><ui-button v-if="snapshot&&run&&can('POST /api/v1/investment-scenarios/:id/decisions')&&['DRAFT','REVIEWED'].includes(selected.body.status)" size="small" type="primary" @click="begin(selected,'decision')">依据此固定排序记录决定</ui-button></div></div><p class="maintenance-hint">人工顺序创建新方案版本，需显式重新计算固定排序。决定绑定实际任务与事实哈希；采购仍需独立执行。</p><article v-for="(c,i) in selected.body.candidates" :key="c.id"><strong>{{candidateName(c)}} · 人工层 {{c.requiredTier}}</strong><p class="maintenance-meta">{{c.tierBasis}} · {{c.constraints?.join('；')}}</p></article><p v-for="(adjust,i) in selected.body.adjustments||[]" :key="'a'+i" class="maintenance-meta">人工顺序 {{adjust.candidateOrder.map(id=>candidateName(selected.body.candidates.find(c=>c.id===id)||{})).join(' → ')}}<br>{{adjust.reason}} · {{adjust.actor}} · {{maintenanceTime(adjust.recordedAt)}}</p><p v-for="(decision,i) in selected.body.decisions||[]" :key="'d'+i" class="maintenance-meta">已决定 {{decision.selectedCandidateIds.map(id=>candidateName(selected.body.candidates.find(c=>c.id===id)||{})).join('、')}}<br>{{decision.reason}} · {{decision.actor}} · {{maintenanceTime(decision.recordedAt)}}<br>固定排序 {{decision.evaluationRunId}} · 事实哈希 {{decision.factsHash}}</p></article>
<ui-dialog v-model="dialog" :title="operation==='draft'?'建立透明投入方案':operation==='adjustment'?'保存人工完整顺序':operation==='decision'?'依据固定版本记录人工决定':'登记方案状态'" width="min(980px,94vw)" :close-on-click-modal="false"><div class="maintenance-dialog-body maintenance-stack"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><p v-if="formLoading" class="maintenance-meta">正在读取候选引用的固定历史实物版本…</p><ui-form label-position="top" :disabled="busy||formLoading"><template v-if="operation==='draft'"><ui-form-item label="方案名称" required><ui-input v-model="form.name"/></ui-form-item><ui-form-item label="同口径规划期" required><ui-date-range v-model="form.planning"/></ui-form-item><ui-checkbox v-model="form.useFinance" :disabled="!can('GET /api/v1/maintenance-costs')">此方案与全部派生结果使用独立资金权限</ui-checkbox><div class="maintenance-grid"><ui-form-item label="单一币种" required><ui-input v-model="form.currency" maxlength="3" @blur="form.currency=form.currency.toUpperCase()"/></ui-form-item><ui-form-item v-if="form.useFinance" label="实际预算（未知留空）"><ui-input v-model="form.budget" placeholder="精确十进制，未知保留空白"/></ui-form-item></div><article v-for="(c,index) in form.candidates" :key="c.id" class="maintenance-card maintenance-stack"><div class="maintenance-toolbar"><h3>候选 {{index+1}}</h3><ui-button size="small" :disabled="form.candidates.length===1" @click="form.candidates.splice(index,1)">移除此候选</ui-button></div><div class="maintenance-grid"><ui-form-item label="固定实物版本" required><ui-select v-model="c.assetRevisionId" @change="c.observationRunId='';c.defectBasisIds=[];c.quoteRevisionId='';resolveObservationAssets(c)"><ui-option v-for="a in assetOptions(c)" :key="a.id" :value="a.id" :label="`${a.body.name} · ${a.body.physicalId} · 版本 ${a.version}`"/></ui-select></ui-form-item><ui-form-item label="实际候选动作" required><ui-select v-model="c.action"><ui-option v-for="id in ['OBSERVE','INSPECT','REPAIR','CALIBRATE','REPLACE']" :key="id" :value="id" :label="stateLabel(id)"/></ui-select></ui-form-item><ui-form-item label="人工必需层（1优先至9）" required><ui-input-number v-model="c.requiredTier" :min="1" :max="9" :precision="0"/></ui-form-item><ui-form-item label="人工必需分层依据" required><ui-input v-model="c.tierBasis"/></ui-form-item><ui-form-item label="固定变化观察来源（选填）"><ui-select v-model="c.observationRunId" clearable><ui-option v-for="r in observationOptions(c)" :key="r.id" :value="r.id" :label="`${maintenanceTime(r.createdAt)} · ${stateLabel(r.status)} · 固定变化观察`"/></ui-select></ui-form-item><ui-form-item label="已核实功能缺陷来源（选填）"><ui-select v-model="c.defectBasisIds" multiple><ui-option v-for="r in defectOptions(c)" :key="r.id" :value="r.id" :label="`${r.body.name} · 功能 ${verificationLabel(r.body.verifications?.at(-1)?.result||'UNKNOWN')} · 版本 ${r.version}`"/></ui-select></ui-form-item><ui-form-item v-if="form.useFinance" label="同币种同规划期未来报价（选填）"><ui-select v-model="c.quoteRevisionId" clearable><ui-option v-for="q in quoteOptions(c)" :key="q.id" :value="q.id" :label="`${q.body.currency} · ${q.body.basis} · 版本 ${q.version}`"/></ui-select></ui-form-item></div><ui-form-item label="实际执行条件与约束（每行一项）"><ui-input v-model="c.constraints" type="textarea"/></ui-form-item></article><ui-button size="small" @click="form.candidates.push(candidate())">增加实际候选</ui-button></template><template v-else-if="operation==='adjustment'"><p class="maintenance-hint">完整顺序保留所有候选。缺少报价仍显示未知，不自动降级必需事项。</p><div v-for="(id,index) in order" :key="id" class="maintenance-toolbar maintenance-card"><span>{{index+1}} · {{candidateName(target.body.candidates.find(c=>c.id===id))}}</span><div class="maintenance-actions"><ui-button size="small" :disabled="index===0" @click="move(index,-1)">上移</ui-button><ui-button size="small" :disabled="index===order.length-1" @click="move(index,1)">下移</ui-button></div></div></template><template v-else-if="operation==='decision'&&fixedDecision"><p class="maintenance-meta">固定任务 {{fixedDecision.run.id}} · 快照 {{fixedDecision.snapshot.version}} · 事实哈希 {{fixedDecision.snapshot.factsHash}}</p><ui-checkbox v-for="c in target.body.candidates" :key="c.id" :model-value="selectedCandidates.includes(c.id)" @update:model-value="$event?selectedCandidates.push(c.id):selectedCandidates=selectedCandidates.filter(id=>id!==c.id)">{{candidateName(c)}}</ui-checkbox><p class="maintenance-hint">记录实际负责人的决定与例外依据，不自动执行采购。</p></template><ui-form-item v-if="operation!=='draft'" label="人工操作依据" required><ui-input v-model="reason" type="textarea" :rows="3"/></ui-form-item></ui-form></div><template #footer><ui-button :disabled="busy" @click="dialog=false">取消</ui-button><ui-button type="primary" :loading="busy||formLoading" @click="save">{{operation==='decision'?'保存人工决定':'保存方案版本'}}</ui-button></template></ui-dialog></section></template>
